/**
 * Slope units (demo). Geometry and Relative Risk Index values are SIMULATED
 * placeholders generated by scripts/generate_demo_data.py — replace with
 * DEM-derived slope units and model output.
 */
import type { Feature, FeatureCollection, Polygon } from 'geojson'
import type { Confidence, DataProvenance, RiskBand, SiteId, Slope } from '@/types/domain'
import { ringBounds, ringCentroid } from '@/lib/geo'
import type { Lang } from '@/lib/i18n'
import raw from './geo/slopes.json'

/** Flat properties carried on the map features (MapLibre reads these). */
export interface SlopeFeatureProps {
  id: string
  site: SiteId
  locality: string
  sector: number
  rri: number
  band: RiskBand
  confidence: Confidence
  slopeDeg: number
  nisar: 'detected' | 'none'
  sensorId: string | null
}

const BANDS: ReadonlySet<string> = new Set(['low', 'moderate', 'high', 'critical'])
const CONF: ReadonlySet<string> = new Set(['low', 'medium', 'high'])
const SITES: ReadonlySet<string> = new Set(['chattogram', 'ukhiya-teknaf'])

function assertFeature(f: unknown): asserts f is Feature<Polygon, SlopeFeatureProps> {
  const feat = f as Feature<Polygon, Record<string, unknown>>
  const p = feat?.properties
  const ok =
    feat?.geometry?.type === 'Polygon' &&
    p != null &&
    typeof p.id === 'string' &&
    typeof p.rri === 'number' &&
    SITES.has(String(p.site)) &&
    BANDS.has(String(p.band)) &&
    CONF.has(String(p.confidence))
  if (!ok) throw new Error(`Invalid slope feature: ${JSON.stringify(p?.id ?? f)}`)
}

const features = (raw as { features: unknown[] }).features.map((f) => {
  assertFeature(f)
  return f
})

export const slopeCollection: FeatureCollection<Polygon, SlopeFeatureProps> = {
  type: 'FeatureCollection',
  features,
}

const ranked = [...features].sort(
  (a, b) => b.properties.rri - a.properties.rri || a.properties.id.localeCompare(b.properties.id),
)

export const slopes: readonly Slope[] = ranked.map((f, i) => {
  const p = f.properties
  const ring = f.geometry.coordinates[0] ?? []
  return {
    id: p.id,
    site: p.site,
    locality: p.locality,
    sector: p.sector,
    relativeRiskIndex: p.rri,
    riskBand: p.band,
    confidence: p.confidence,
    slopeDegrees: p.slopeDeg,
    nisarChange: p.nisar,
    sensorId: p.sensorId,
    rank: i + 1,
    center: ringCentroid(ring),
    bounds: ringBounds(ring),
  }
})

const byId = new Map(slopes.map((s) => [s.id, s]))

export function getSlope(id: string | null | undefined): Slope | undefined {
  return id ? byId.get(id) : undefined
}

export const slopeFeatureById = new Map(features.map((f) => [f.properties.id, f]))

export const SLOPE_PROVENANCE = {
  geometry: {
    kind: 'simulated',
    source: 'Demo slope units near named hill localities (positions approximate)',
    note: 'Replace with NASADEM-derived slope units',
  },
  risk: {
    kind: 'simulated',
    source: 'Placeholder Relative Risk Index',
    validation: 'pending',
    note: 'Replace with model output (NISAR change + GPM + NASADEM + Landslide Catalog)',
  },
  terrain: {
    kind: 'simulated',
    source: 'Placeholder slope angle',
    note: 'Replace with NASADEM-derived slope',
  },
} as const satisfies Record<string, DataProvenance>

